const input = $input.first().json;

// Spec 13: 'Do not store credentials inside Code nodes or plain-text sheets.' The Errors tab
// IS a plain-text sheet, and n8n error payloads from HTTP/OAuth node failures can include
// Authorization headers, tokens or API keys in the message/stack. Redact before it ever
// reaches error_summary, which is the one place in this whole system that captures raw
// failure content from every other workflow.
function redactSensitive(str) {
  return String(str || '')
    .replace(/Bearer\s+[A-Za-z0-9\-_.]+/gi, 'Bearer [REDACTED]')
    .replace(/"(access_token|refresh_token|api_key|apikey|password|secret|client_secret)"\s*:\s*"[^"]*"/gi, '"$1":"[REDACTED]"')
    .replace(/(access_token|refresh_token|api_key|apikey|password|secret|client_secret)=[^&\s"']+/gi, '$1=[REDACTED]');
}

const workflowName = input.workflow?.name || 'Unknown workflow';
const workflowId = input.workflow?.id || '';
const executionId = input.execution?.id || '';
const executionUrl = input.execution?.url || '';
const lastNode = input.execution?.lastNodeExecuted || input.node?.name || 'Unknown node';
const rawErrorMessage = input.execution?.error?.message
  || input.execution?.error?.description
  || JSON.stringify(input.execution?.error || {}).slice(0, 500);
const errorMessage = redactSensitive(rawErrorMessage);

// Best-effort extraction of a lead_id or email from the error payload, without exposing
// unnecessary sensitive content in the log.
const rawString = redactSensitive(JSON.stringify(input).slice(0, 3000));
const leadIdMatch = rawString.match(/"lead_id"\s*:\s*"([^"]+)"/);
const emailMatch = rawString.match(/[\w.+-]+@[\w-]+(?:\.[\w-]+)*\.[a-zA-Z]{2,}/);

const leadId = leadIdMatch ? leadIdMatch[1] : '';
const relatedEmail = emailMatch ? emailMatch[0] : '';

return [{ json: {
  workflow_name: workflowName,
  workflow_id: workflowId,
  execution_id: executionId,
  execution_url: executionUrl,
  failed_node: lastNode,
  error_summary: errorMessage,
  lead_id: leadId,
  related_email: relatedEmail,
  occurred_at_utc: new Date().toISOString()
} }];

const item = $('CODE - Extract Error Details').first().json;
const priorErrors = $input.all();
const wf = item.workflow_name.toLowerCase();
const node = item.failed_node.toLowerCase();

let severity = 'Medium';

// Section 13.3: Critical = intake/scoring/widespread result-email failure.
const criticalSignals = ['wf-01', 'lead intake', 'calculate scores', 'build lead record', 'upsert lead', 'normalize input'];
// High = A-level alerts failing, or booking/reply stop conditions failing.
const highSignals = ['wf-03', 'a-level', 'wf-05', 'booking', 'wf-06', 'reply', 'unsubscribe', 'wf-02', 'result email'];
// Note: spec 13.3's Medium example is 'Dashboard delay' (WF-07) - there is deliberately no
// signal list that routes WF-07 to Low. Its own example, 'non-blocking copy or cosmetic
// issue', doesn't correspond to anything that throws an exception in the first place, so Low
// is left as a manual severity a human can set after reviewing the Errors tab, not something
// this classifier assigns automatically.

if (criticalSignals.some((s) => wf.includes(s) || node.includes(s))) {
  severity = 'Critical';
} else if (highSignals.some((s) => wf.includes(s) || node.includes(s))) {
  severity = 'High';
}

// Spec 13.3 explicitly distinguishes a single result-email failure (High) from a 'widespread
// result-email failure' (Critical). Generalized to any workflow: 3+ failures from the same
// workflow within the last hour indicates a systemic problem, not an isolated one-off.
const WIDESPREAD_THRESHOLD = 3;
const oneHourAgoMs = Date.now() - 60 * 60 * 1000;
const recentSameWorkflowFailures = priorErrors.filter((row) => {
  const t = new Date(row.json.event_at_utc || 0).getTime();
  return !isNaN(t) && t >= oneHourAgoMs;
}).length;

if (severity !== 'Critical' && recentSameWorkflowFailures >= WIDESPREAD_THRESHOLD) {
  severity = 'Critical';
}

const needsImmediateNotification = severity === 'Critical' || severity === 'High';

return [{ json: { ...item, severity, recent_same_workflow_failures: recentSameWorkflowFailures, needs_immediate_notification: needsImmediateNotification } }];

const errorItem = $('CODE - Classify Severity').first().json;
const configRows = $input.all();

const config = {};
for (const row of configRows) {
  const key = row.json.Key ?? row.json.key;
  const value = row.json.Value ?? row.json.value;
  if (key) config[key] = value;
}

return [{ json: { ...errorItem, owner_email: config.OWNER_EMAIL || '' } }];
